// ==== VORLTEX TEK DOSYA SUNUCU ====
// Çalıştır:  node server.js   (ws kütüphanesi yoksa kendisi kurar)
// Oyun, gizlilik sayfası ve online sunucu hepsi bu dosyada.
//   /            -> oyun        /privacy.html -> gizlilik politikası
// Ortam değişkenleri: PORT, GOOGLE_CLIENT_ID (Google girişi), BANNED_EMAILS
const zlib = require("zlib");
try { require.resolve("ws"); } catch (e) {
  console.log("ws kuruluyor...");
  require("child_process").execSync("npm install ws --no-save --no-audit --no-fund", { stdio: "inherit", cwd: __dirname });
}
const GAME_GZ = "";
const PRIV_GZ = "";
const GAME = zlib.gunzipSync(Buffer.from(GAME_GZ, "base64")).toString("utf8");
const PRIV = zlib.gunzipSync(Buffer.from(PRIV_GZ, "base64")).toString("utf8");
// VORLTEX online sunucusu: oyuncuları odalarda buluşturur, konum/vuruş/sohbet mesajlarını iletir.
const http = require("http");
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const https = require("https");
const { WebSocketServer } = require("ws");

const PORT = process.env.PORT || 8787;
const MAX_CLIENTS = 300;      // aynı anda en fazla oyuncu
const MAX_MSG = 40000; const SMALL_MSG = 2048; const SAVE_MAX = 30000; const DATA_DIR = process.env.DATA_DIR || path.join(__dirname, "data");         // bir mesajın en büyük boyutu (bayt)
const RATE = 80;              // bir oyuncunun saniyedeki en fazla mesajı
const TICK = 100;             // oyuncu listesi yayın aralığı (ms)

// --- Google giriş doğrulaması ---
// GOOGLE_CLIENT_ID verilirse, oyuncular Google ID token'ı ile doğrulanmadan odalara giremez.
const GOOGLE_CLIENT_ID = process.env.GOOGLE_CLIENT_ID || "";
const TOKENINFO_URL = process.env.TOKENINFO_URL || "https://oauth2.googleapis.com/tokeninfo";
const BANNED = new Set((process.env.BANNED_EMAILS || "").toLowerCase().split(",").map(s => s.trim()).filter(Boolean));
const REQUIRE_AUTH = !!GOOGLE_CLIENT_ID;
const tokCache = new Map(); // token -> {email, exp}

function verifyToken(token) {
  return new Promise((resolve) => {
    token = String(token || "");
    if (token.length < 20 || token.length > 3000) return resolve(null);
    const hit = tokCache.get(token);
    if (hit && hit.exp * 1000 > Date.now()) return resolve(hit);
    const u = new URL(TOKENINFO_URL); u.searchParams.set("id_token", token);
    const lib = u.protocol === "http:" ? http : https;
    const req = lib.get(u, { timeout: 6000 }, (res) => {
      let body = ""; res.on("data", (d) => { body += d; if (body.length > 8000) req.destroy(); });
      res.on("end", () => {
        try {
          const j = JSON.parse(body);
          const ok = res.statusCode === 200 && j.aud === GOOGLE_CLIENT_ID &&
            /^(https:\/\/)?accounts\.google\.com$/.test(j.iss || "") &&
            (j.email_verified === true || j.email_verified === "true") &&
            /^[a-z0-9._%+-]{3,}@gmail\.com$/i.test(j.email || "") && Number(j.exp) * 1000 > Date.now();
          if (!ok) return resolve(null);
          const r = { email: j.email.toLowerCase(), exp: Number(j.exp) };
          tokCache.set(token, r); if (tokCache.size > 2000) tokCache.clear();
          resolve(r);
        } catch (e) { resolve(null); }
      });
    });
    req.on("error", () => resolve(null)); req.on("timeout", () => { req.destroy(); resolve(null); });
  });
}

const server = http.createServer((req, res) => {
  const u = (req.url || "/").split("?")[0];
  if (u === "/" || u === "/index.html") { res.writeHead(200, { "content-type": "text/html; charset=utf-8" }); return res.end(GAME.replace("@@GCID@@", process.env.GOOGLE_CLIENT_ID || "")); }
  if (u === "/privacy.html") { res.writeHead(200, { "content-type": "text/html; charset=utf-8" }); return res.end(PRIV); }
  res.writeHead(200, { "content-type": "text/plain; charset=utf-8", "access-control-allow-origin": "*" });
  res.end("VORLTEX sunucusu çalışıyor. Oyuncu: " + clients.size + " · Kuyrukta: " + queue.size + (REQUIRE_AUTH ? " · Google doğrulaması AÇIK" : " · Google doğrulaması KAPALI") + "\n");
});
// --- Arkadaşlar: herkese açık oyuncu kodu (e-postadan türetilir, e-posta paylaşılmaz) ---
const NAMES_FP = path.join(DATA_DIR, "names.json");
const LB_FP = path.join(DATA_DIR, "lb.json"); let lb = {}; try { lb = JSON.parse(fs.readFileSync(LB_FP, "utf8")) || {}; } catch (e) {} let lbDirty = false;
setInterval(() => { if (!lbDirty) return; lbDirty = false; try { fs.mkdirSync(DATA_DIR, { recursive: true }); fs.writeFileSync(LB_FP + ".tmp", JSON.stringify(lb)); fs.renameSync(LB_FP + ".tmp", LB_FP); } catch (e) {} }, 10000);
function lbSeason() { const d = new Date(); return (d.getUTCFullYear() - 2026) * 12 + d.getUTCMonth() - 9; }
function lbRoll() { const cur = lbSeason(); if (lb._s === cur) return; if (lb._s != null) for (const k of Object.keys(lb)) if (k !== "_s") lb[k].rp = Math.floor(lb[k].rp / 2); lb._s = cur; lbDirty = true; }
function lbAdd(pid, d) { if (!pid) return; lbRoll(); const o = lb[pid] || { n: "Oyuncu", rp: 0 }; o.n = clean(pnames[pid] || o.n, 16); o.rp = Math.max(0, o.rp + d); lb[pid] = o; lbDirty = true; }
function lbTop() { lbRoll(); return Object.entries(lb).filter(([p]) => p !== "_s").map(([p, o]) => ({ p, n: o.n, rp: o.rp })).sort((a, b) => b.rp - a.rp); }
let pnames = {}; try { pnames = JSON.parse(fs.readFileSync(NAMES_FP, "utf8")) || {}; } catch (e) {}
let namesDirty = false;
setInterval(() => { if (!namesDirty) return; namesDirty = false; try { fs.mkdirSync(DATA_DIR, { recursive: true }); fs.writeFileSync(NAMES_FP + ".tmp", JSON.stringify(pnames)); fs.renameSync(NAMES_FP + ".tmp", NAMES_FP); } catch (e) {} }, 30000);
function pidOf(email) { return crypto.createHash("sha256").update("vltx|" + email).digest("hex").slice(0, 8).toUpperCase(); }
const wss = new WebSocketServer({ server, maxPayload: MAX_MSG });
const clients = new Map(); // id -> {ws, presence, n, t}
let dirty = false;

// --- Eşleşme (matchmaking) ---
// Oyuncu kuyruğa girer; aynı moddaki oyuncular RP farkı yetince eşleşir. Dereceli kuyrukta aralık bekledikçe genişler.
const MM_NEED = { arena: 2, "1v1ak": 2, "1v1awp": 2, "2v2ak": 4, "2v2awp": 4 };
const queue = new Map(); // id -> {mode, rp, rk, t}
// Dereceli maç sonucu doğrulaması: RP yalnızca TÜM oyuncuların bildirimi aynı kazananı gösteriyorsa verilir.
const mrooms = new Map(); // room -> {ids:Set, need, t0, reports:Map, left:Set, done}
const MIN_MATCH_MS = Number(process.env.MIN_MATCH_MS) || 25000;
function mrEval(room, r) {
  if (r.done) return;
  const alive = r.ids.size - r.left.size;
  if (r.reports.size < r.need && !(r.left.size > 0 && r.reports.size >= alive && alive > 0)) return;
  r.done = true;
  const aged = Date.now() - r.t0 >= MIN_MATCH_MS;
  const wins = new Set(); for (const [, v] of r.reports) wins.add(v.w ? v.tm : (v.tm === "CT" ? "T" : "CT"));
  let ok = aged && wins.size === 1;
  if (ok && r.left.size > 0) for (const [, v] of r.reports) if (!v.w) ok = false; // rakibi ayrılan taraf yalnızca galibiyet bildirebilir
  const W = ok ? [...wins][0] : null;
  for (const [id, v] of r.reports) { const c = clients.get(id); if (c && ok) lbAdd(c.pid, v.tm === W ? 25 : -15); if (c) send(c.ws, ok ? { t: "rp", d: v.tm === W ? 25 : -15 } : { t: "rp", d: 0, disp: 1 }); }
  setTimeout(() => mrooms.delete(room), 60000);
}
setInterval(() => { const n = Date.now(); for (const [k, r] of mrooms) if (n - r.t0 > 3600000) mrooms.delete(k); }, 600000);
const mmWindow = (e, now) => e.rk ? 120 + 30 * ((now - e.t) / 1000) : Infinity;
function mmTick() {
  const now = Date.now();
  const groups = new Map();
  for (const [id, e] of queue) { const c = clients.get(id); if (!c) { queue.delete(id); continue; } const k = e.mode + (e.rk ? "|r" : "|q"); if (!groups.has(k)) groups.set(k, []); groups.get(k).push({ id, e }); }
  for (const [k, arr0] of groups) {
    const need = MM_NEED[k.split("|")[0]]; let arr = arr0.slice().sort((a, b) => a.e.rp - b.e.rp);
    let found = true;
    while (found && arr.length >= need) {
      found = false;
      for (let i = 0; i + need <= arr.length; i++) {
        const g = arr.slice(i, i + need), spread = g[need - 1].e.rp - g[0].e.rp, w = Math.min(...g.map(x => mmWindow(x.e, now)));
        if (spread <= w) {
          const room = k.split("|")[0] + "_" + (k.endsWith("|r") ? "r" : "q") + rid();
          if (k.endsWith("|r")) mrooms.set(room, { ids: new Set(g.map(x => x.id)), need, t0: now, reports: new Map(), left: new Set(), done: false });
          for (const x of g) { queue.delete(x.id); const c = clients.get(x.id); if (c) send(c.ws, { t: "found", room, mode: k.split("|")[0], rk: k.endsWith("|r") ? 1 : 0 }); }
          arr = arr.filter(x => !g.includes(x)); found = true; break;
        }
      }
    }
    for (const x of arr) { const c = clients.get(x.id); if (c) send(c.ws, { t: "mmst", n: arr.length, need, w: Math.floor((now - x.e.t) / 1000), win: Math.round(mmWindow(x.e, now)) }); }
  }
}
setInterval(mmTick, 1000);

const rid = () => Math.random().toString(36).slice(2, 10);
const clean = (v, n) => String(v == null ? "" : v).replace(/[<>]/g, "").slice(0, n);

function sanitizePresence(p) {
  if (!p || typeof p !== "object") return {};
  const o = {};
  for (const k of ["sel", "rm", "tm", "ag", "hc", "hm", "hmap"]) if (p[k] != null) o[k] = clean(p[k], 40);
  o.n = clean(p.n, 16);
  for (const k of ["x", "z", "yw"]) if (typeof p[k] === "number" && isFinite(p[k])) o[k] = Math.max(-500, Math.min(500, p[k]));
  if (p.al === 0 || p.al === 1) o.al = p.al;
  return o;
}
function sanitizeData(d) {
  if (!d || typeof d !== "object") return {};
  const o = {};
  for (const k in d) {
    const v = d[k];
    if (typeof v === "number" && isFinite(v)) o[k] = v;
    else if (typeof v === "string") o[k] = clean(v, 200);
  }
  return o;
}
function send(ws, obj) { if (ws.readyState === 1) ws.send(JSON.stringify(obj)); }

wss.on("connection", (ws) => {
  if (clients.size >= MAX_CLIENTS) { send(ws, { t: "full" }); ws.close(); return; }
  const id = rid();
  const c = { ws, presence: {}, cnt: 0, win: Date.now(), alive: true, authed: !REQUIRE_AUTH, email: null };
  clients.set(id, c);
  send(ws, { t: "hello", id, auth: REQUIRE_AUTH });
  if (REQUIRE_AUTH) setTimeout(() => { if (!c.authed) { try { ws.close(); } catch (e) {} } }, 15000);
  dirty = true;
  ws.on("pong", () => { c.alive = true; });
  ws.on("message", (raw) => {
    const now = Date.now();
    if (now - c.win > 1000) { c.win = now; c.cnt = 0; }
    if (++c.cnt > RATE) return;
    if (raw.length > SMALL_MSG && !String(raw).startsWith('{"t":"sset"')) return;
    let m; try { m = JSON.parse(raw); } catch (e) { return; }
    if (!m || typeof m !== "object") return;
    if (m.t === "auth") {
      if (!REQUIRE_AUTH || c.verifying) return;
      c.verifying = true;
      verifyToken(m.token).then((r) => {
        c.verifying = false;
        if (!r) { send(ws, { t: "autherr", msg: "Google girişi doğrulanamadı. Çıkış yapıp tekrar giriş yap." }); return; }
        if (BANNED.has(r.email)) { send(ws, { t: "autherr", msg: "Bu hesap engellendi." }); try { ws.close(); } catch (e) {} return; }
        // aynı hesap ikinci kez bağlanırsa eskisini at (tek hesap = tek oturum)
        for (const [oid, o] of clients) if (oid !== id && o.email === r.email) { send(o.ws, { t: "kicked" }); try { o.ws.close(); } catch (e) {} clients.delete(oid); queue.delete(oid); }
        c.email = r.email; c.pid = pidOf(r.email); c.authed = true; send(ws, { t: "authok", pid: c.pid }); dirty = true;
      });
      return;
    }
    if (!c.authed) return;
    if (m.t === "sget" || m.t === "sset" || m.t === "sdel") {
      if (!c.email) { send(ws, { t: "sdata", na: 1 }); return; }
      const fp = path.join(DATA_DIR, crypto.createHash("sha256").update(c.email).digest("hex").slice(0, 40) + ".json");
      try {
        if (m.t === "sget") { let o = null; try { o = JSON.parse(fs.readFileSync(fp, "utf8")); } catch (e) {} send(ws, { t: "sdata", ts: o ? o.ts : 0, d: o ? o.d : null }); }
        else if (m.t === "sdel") { try { fs.unlinkSync(fp); } catch (e) {} send(ws, { t: "sdel" }); }
        else {
          if (now - (c.sw || 0) < 1500) return; c.sw = now;
          if (typeof m.d !== "string" || m.d.length > SAVE_MAX) return;
          let sv; try { sv = JSON.parse(m.d); } catch (e) { return; }

          fs.mkdirSync(DATA_DIR, { recursive: true });
          fs.writeFileSync(fp + ".tmp", JSON.stringify({ ts: Number(m.ts) || Date.now(), d: m.d })); fs.renameSync(fp + ".tmp", fp);
          send(ws, { t: "sok", ts: Number(m.ts) || 0 });
        }
      } catch (e) { send(ws, { t: "serr" }); }
      return;
    }
    if (m.t === "lbq") {
      if (now - (c.lbw || 0) < 2000) return; c.lbw = now;
      const all = lbTop(), idx = c.pid ? all.findIndex((x) => x.p === c.pid) : -1;
      send(ws, { t: "lb", l: all.slice(0, 50), me: idx >= 0 ? idx + 1 : 0 }); return;
    }
    if (m.t === "fq") {
      if (!c.pid || now - (c.fqw || 0) < 1500) return; c.fqw = now;
      const want = Array.isArray(m.p) ? m.p.slice(0, 50).map((x) => String(x).toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 8)).filter((x) => x.length === 8) : [];
      const online = new Map(); for (const [, o] of clients) if (o.pid) online.set(o.pid, o);
      send(ws, { t: "fs", l: want.map((p) => { const o = online.get(p); return { p, n: pnames[p] || "", on: o ? 1 : 0, h: o && o.presence && o.presence.hm ? clean(o.presence.hm, 12) : "" }; }) });
      return;
    }
    if (m.t === "finv") {
      if (!c.pid || now - (c.fiw || 0) < 3000) return; c.fiw = now;
      const to = String(m.to || "").toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 8), rm = clean(m.rm, 12), md = clean(m.md, 12);
      if (!to || !rm) return;
      for (const [, o] of clients) if (o.pid === to) { send(o.ws, { t: "finv", p: c.pid, n: pnames[c.pid] || "Oyuncu", rm, md }); break; }
      return;
    }
    if (m.t === "mmq") {
      const mode = clean(m.mode, 12);
      if (!MM_NEED[mode]) return;
      const rp = Math.max(0, Math.min(99999, Number(m.rp) || 0));
      queue.set(id, { mode, rp, rk: m.rk ? 1 : 0, t: Date.now() }); return;
    }
    if (m.t === "mmx") { queue.delete(id); return; }
    if (m.t === "mend") {
      const room = c.presence && c.presence.rm, r = room && mrooms.get(room);
      if (!r || r.done || !r.ids.has(id) || r.reports.has(id)) return;
      const tm = m.tm === "T" ? "T" : "CT";
      r.reports.set(id, { tm, w: m.w ? 1 : 0 }); mrEval(room, r); return;
    }
    if (m.t === "pres") { c.presence = sanitizePresence(m.p); if (c.pid && c.presence.n && pnames[c.pid] !== c.presence.n) { pnames[c.pid] = c.presence.n; namesDirty = true; } if (c.presence.rm) queue.delete(id); dirty = true; }
    else if (m.t === "emit") {
      const topic = clean(m.topic, 12);
      if (!["hit", "kill", "chat"].includes(topic)) return;
      if (!c.presence.rm) return;
      const data = sanitizeData(m.data);
      if (topic === "hit" || topic === "kill") {
        // hedefe doğrudan ilet
        const target = clients.get(data.to);
        if (topic === "hit") { data.d = Math.max(0, Math.min(150, Number(data.d) || 0)); c.hits = (c.hits || 0) + 1; if (now - (c.hw || 0) > 1000) { c.hw = now; c.hits = 1; } if (c.hits > 16) return; if (data.d <= 0) return; if (target && target.presence.rm === c.presence.rm) { target.lastHitBy = id; target.lastHitT = now; } }
        if (topic === "kill") {
          // sahte öldürme engeli: ölen oyuncu, ancak yakın zamanda ona vuran kişiye öldürme bildirebilir (tek seferlik)
          if (c.lastHitBy !== data.to || now - (c.lastHitT || 0) > 12000) return;
          c.lastHitBy = null;
        }
        if (target && target.presence.rm === c.presence.rm) send(target.ws, { t: "msg", topic, data: Object.assign({}, data, { from: id }), from: id });
      } else {
        const room = c.presence.rm;
        for (const [, o] of clients) if (o.presence.rm === room) send(o.ws, { t: "msg", topic, data, from: id });
      }
    }
  });
  ws.on("close", () => { clients.delete(id); queue.delete(id); dirty = true; for (const [room, r] of mrooms) if (r.ids.has(id) && !r.done && !r.reports.has(id)) { r.left.add(id); mrEval(room, r); } });
  ws.on("error", () => {});
});

// Her oyuncuya: kendi odasındakilerin tüm bilgisi, diğerlerinin sadece menü bilgisi
setInterval(() => {
  if (!dirty) return;
  dirty = false;
  const list = [...clients.entries()];
  for (const [id, c] of list) {
    const rm = c.presence.rm;
    const peers = list.map(([pid, o]) => {
      const p = o.presence;
      if (rm && p.rm === rm) return { peer: pid, presence: p };
      return { peer: pid, presence: { sel: p.sel, rm: p.rm, hc: p.hc, hm: p.hm, hmap: p.hmap } };
    });
    send(c.ws, { t: "peers", peers });
  }
}, TICK);
// Konum değişiklikleri sürekli geldiği için odadakiler her zaman yayınlanır
setInterval(() => { dirty = true; }, 250);

// Kopan bağlantıları temizle
setInterval(() => {
  for (const [id, c] of clients) {
    if (!c.alive) { try { c.ws.terminate(); } catch (e) {} clients.delete(id); queue.delete(id); dirty = true; continue; }
    c.alive = false; try { c.ws.ping(); } catch (e) {}
  }
}, 20000);

server.listen(PORT, () => console.log("VORLTEX sunucusu " + PORT + " portunda" + (REQUIRE_AUTH ? " (Google doğrulaması açık)" : " (UYARI: GOOGLE_CLIENT_ID yok, doğrulama kapalı)")));
